for(let year=2005;year<=2026;year++){
  let coverage="No project observations imported",usable="Do not infer no change",next="Locate final CAISO plan; record project table, PDF/printed page, and row citation before import",status="Backlog";
  if(year===2005){coverage="Pre-plan: CAISO's new planning process began in summer 2005";usable="Start-year context only; no annual-plan project observation";next="Use predecessor utility/CPUC/FERC records only when a project needs a pre-2006 baseline. Citation: SRC-CAISO-TPP-2006-MEMO, PDF p. 1.";status="Pre-plan";}
  if(year===2006){coverage="First CAISO annual plan: Operating Guide excerpt imported";usable="12 cited PG&E rows: scope, system impact, target ISD, and MVA capacity where stated; no cost. The excerpt is not the full plan.";next="SRC-CAISO-TPP-2006-OPERATING-GUIDE-EXCERPT, PDF p. 10 (slide 10), rows 1–12. Locate the complete plan before using 2006 for totals or crosswalks.";status="Partial";}
  if(year===2007||year===2009||year===2010||year===2011){coverage="Annual CAISO-plan project records not yet imported";usable="Do not use for trend totals yet";next="Locate final plan for this cycle and capture each project table's PDF/printed page and table row. Preserve original cost text, target ISD, scope, and status.";status="Backlog";}
  if(year===2008){coverage="2008 CAISO plan: Tables 3-1 to 3-13 imported";usable="178 cited observations: 85 previously approved-project status rows; 36 CAISO management-approved proposals; 18 Board-required proposals; 3 not-approved or in-review proposals; and 36 short-term-plan recommendations. Recommendation rows retain their needs, recommendation text, and reported status; they are not approval evidence and do not report cost.";next="Tables 3-11–3-13 are now imported. Next: add primary project documents for source-verified costs, routes, scope, and outcomes before treating recommendations as project continuations.";status="Imported";}
  if(year>=2012&&year<=2019){coverage=`${year}-${year+1} CAISO TPP era: final plan project tables not yet imported`;usable="Two-year plan cycle requires a plan-cycle label; do not pretend this is a yearly observation";next="Locate the Board-approved plan for the applicable cycle; extract approval/status tables with project row, PDF/printed page, cost text, ISD, and scope.";status="Backlog";}
  if(year===2020||year===2021){coverage="CAISO TDF annual-plan field for 89 projects";usable="Schedule/status baseline only";next="Add annual CAISO approval-plan project rows";status="Partial";}
  if(year===2022){coverage="CAISO TDF Q1–Q4 for 89 projects";usable="Quarterly schedule/status observations";next="Add cost/path/size evidence from project documents where needed";status="Imported";}
  if(year===2023){coverage="CAISO TDF Q1–Q2 plus October release";usable="Schedule/status observations through October 2023";next="TDF reports do not add cost/path/size fields; add project documents where those fields are needed";status="Imported";}
  if(year===2024){coverage="CAISO TDF January and July; public TPR releases for all three IOUs";usable="TDF schedule/status and TPR project-level cost/path/size fields where reported";next="Add project documents for route, scope, and final cost validation";status="Imported";}
  if(year===2025){coverage="CAISO TDF January and July; public TPR releases for all three IOUs";usable="TDF schedule/status and TPR project-level cost/path/size fields where reported";next="Add project documents for route, scope, and final cost validation";status="Imported";}
  if(year===2026){coverage="CAISO TDF January and July; current TPR: PG&E May, SCE June, SDG&E July";usable="TDF schedule/status and current utility project fields where reported";next="Add later 2026 utility releases when posted";status="Imported";}
  coverageRows.push([year,coverage,usable,next,status]);
}
